checker_details.tests:
from solution import fit

def test_examples():
    assert fit('hello world', 8) == 'hello w…'
    assert fit('hello', 5) == 'hello'

def test_wide_boundary():
    # 한 = 2 cols each; width 4: available 3 -> one char (2) + …
    assert fit('한국어', 4) == '한…'

def test_wide_fits():
    assert fit('한국', 4) == '한국'

def test_wide_exact_available():
    assert fit('한국어', 5) == '한국…'

def test_combining_kept():
    s = 'e\u0301abcdef'
    assert fit(s, 4) == 'e\u0301ab…'

def test_combining_fits_zero_width():
    s = 'abc\u0301'
    assert fit(s, 3) == s

def test_zwj_stays_with_prev():
    s = 'a\u200db' + 'cdef'
    assert fit(s, 3) == 'a\u200db…'

def test_cut_drops_trailing_marks_with_char():
    s = 'ab' + 'c\u0301' + 'def'
    assert fit(s, 3) == 'ab…'

def test_width_one():
    assert fit('abc', 1) == '…'

def test_width_one_wide():
    assert fit('한국', 1) == '…'

def test_fullwidth_letters():
    assert fit('ＡＢＣ', 5) == 'ＡＢ…'

def test_empty():
    assert fit('', 1) == ''

def test_trailing_zero_width_fits():
    s = 'abc' + '\u0301\u0301'
    assert fit(s, 3) == s
